#include "index_page_oracle.h"
#include <chrono>
template<class Handler>Handler handler(size_t entries){Handler h;h.dir_path="/ordinary-directory/";for(size_t i=0;i<entries;++i)h.dir_files.insert("ordinary-file-"+std::to_string(i)+".txt");return h;}
static size_t entries(const std::string &name){if(name=="10")return 10;if(name=="100")return 100;if(name=="1000")return 1000;throw std::runtime_error("workload");}
static void check(size_t count){auto old=handler<upstream_index::StaticHandler>(count);auto candidate=handler<candidate_index::StaticHandler>(count);IndexBuffer a(65536),b(65536);a.length=b.length=0;auto n=old.make_index_page(&a),m=candidate.make_index_page(&b);if(n!=m||a.storage!=b.storage||a.size!=b.size||a.events!=b.events)throw std::runtime_error("native/Rust output/growth mismatch");}
template<class Handler>int measure(size_t count,const std::string &engine,const std::string &name,size_t iterations){auto h=handler<Handler>(count);IndexBuffer buffer(65536);buffer.length=0;size_t expected=h.make_index_page(&buffer);auto image=buffer.storage;unsigned allocations=buffer.calls;auto step=[&](){buffer.length=0;return h.make_index_page(&buffer);};for(unsigned i=0;i<128;++i)step();size_t signature=0;auto start=std::chrono::steady_clock::now();for(size_t i=0;i<iterations;++i)signature+=step();auto end=std::chrono::steady_clock::now();if(signature!=iterations*expected||buffer.storage!=image||buffer.calls!=allocations)throw std::runtime_error("timed output/allocation differs");check(count);std::cout<<"{\"engine\":\""<<engine<<"\",\"workload\":\""<<name<<"\",\"operations\":"<<iterations<<",\"ns\":"<<std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count()<<",\"signature\":"<<signature<<",\"errors\":0}\n";return 0;}
int main(int argc,char **argv){try{if(argc==2&&std::string(argv[1])=="--check"){for(size_t count:{10U,100U,1000U})check(count);std::cout<<"{\"warm_directory_page_workloads\":3,\"errors\":0}\n";return 0;}if(argc!=4)throw std::runtime_error("engine workload iterations required");std::string engine=argv[1],name=argv[2];size_t iterations=std::stoull(argv[3]);if(!iterations)throw std::runtime_error("iterations");check(entries(name));if(engine=="native")return measure<upstream_index::StaticHandler>(entries(name),engine,name,iterations);if(engine=="rust")return measure<candidate_index::StaticHandler>(entries(name),engine,name,iterations);throw std::runtime_error("engine");}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
